/** True when a due date exists and its calendar day on the zone's clock has ended. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < dateOf(reference, timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The window a digest covers. It ends at the most recent `hour:00` on the
 * zone's clock at or before `reference` — today's if that has passed,
 * yesterday's otherwise — and starts at the same hour on the calendar day
 * before. Across a DST change the window is 23 or 25 hours long.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digest hour must be 0-23, got ${digestHour}`);
  }

  const today = dateOf(reference, timeZone);
  const endDate =
    instantAtWall(today, digestHour, timeZone) > reference.getTime()
      ? shiftDate(today, -1)
      : today;

  return {
    start: toIsoTimestamp(
      new Date(instantAtWall(shiftDate(endDate, -1), digestHour, timeZone)),
    ),
    end: toIsoTimestamp(new Date(instantAtWall(endDate, digestHour, timeZone))),
  };
}

