 * Owner D. Matches `/[orgSlug]`, so the overview page gets an activity rail
 * alongside it. The feed is a separate render tree from the main page, which is
 * the point of the parallel route: a slow activity query cannot hold up the
 * overview.
 *
 * The panel is `activity_feed`-gated; when the flag is off it renders nothing
 * and the aside collapses.
 */

import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { groupByDay, listActivity } from "@/server/services/activity-service";
import { loadTenantContext } from "../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

const PANEL_ACTIVITY_LIMIT = 15;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  if (!isEnabled("activity_feed", buildFlagContext(actor, org))) {
    return null;
  }
  if (!can(actor, "activity:read", { kind: "activity", orgId: org.id })) {
    return null;
  }

  const page = await listActivity(actor, {
    orgId: org.id,
    limit: PANEL_ACTIVITY_LIMIT,
  });
  const groups = groupByDay(page.items);

  return (
    <section className="p-6">
      <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
        Recent activity
      </h2>

      <div className="mt-4 space-y-6">
        {groups.map((group) => (
          <div key={group.day}>
            <p className="text-xs uppercase tracking-wide text-slate-400">
              {group.day}
            </p>
            <ul className="mt-2 space-y-2 text-sm text-slate-600">
              {group.events.map((event) => (
                <li key={event.id}>{event.summary}</li>
              ))}
            </ul>
          </div>
        ))}
      </div>
    </section>
  );
}

/**
 * Organization activity feed; requires `activity:read` and the `activity_feed`
 * flag.
 *
 * Owner D. Two gates that fail differently on purpose: a missing permission is
 * a 404 (the page should not exist for you), a disabled flag is an explanation
 * (the page exists, your plan does not include it).
 *
 * Must call (do not reimplement): can, isEnabled
 */

import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { ActivityFeed } from "@/components/domain/activity/activity-feed";
import { EmptyState } from "@/components/ui/empty-state";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { groupByDay, listActivity } from "@/server/services/activity-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { listMembers } from "@/server/services/member-service";
import { searchParamsPaginationSchema } from "@/schemas/pagination";
import type { User } from "@/types/member";
import { loadTenantContext } from "../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Activity",
};

const MEMBER_LOOKUP_LIMIT = 100;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  if (!can(actor, "activity:read", { kind: "activity", orgId: org.id })) {
    notFound();
  }

  if (!isEnabled("activity_feed", buildFlagContext(actor, org))) {
    return (
      <EmptyState
        title="The activity feed is not part of this plan"
        description="Upgrade in Settings → Billing to keep an audit trail of every change."
      />
    );
  }

  const pagination = searchParamsPaginationSchema.parse(search);

  const [page, members] = await Promise.all([
    listActivity(actor, {
      orgId: org.id,
      limit: pagination.perPage,
      cursor: pagination.cursor ?? null,
    }),
    listMembers(actor, { orgId: org.id, limit: MEMBER_LOOKUP_LIMIT }),
  ]);

  const actors: Record<string, User> = {};
  for (const member of members.items) {
    actors[member.userId] = member.user;
  }

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-2xl font-semibold tracking-tight">Activity</h1>
        <p className="mt-1 text-sm text-slate-600">
          Every change made in {org.name}, newest first.
        </p>
      </header>

      <ActivityFeed groups={groupByDay(page.items)} actors={actors} actor={actor} />
    </div>
  );
}

/**
 * Cron-style trigger for the digest job.
 *
 * Owner D. The route is a trigger, not the job: `runDigestEmailJob` decides
 * which organizations are due based on their `digestHourUtc`, so calling this
 * every hour is correct and calling it twice in one hour is harmless.
 *
 * Must call (do not reimplement): runDigestEmailJob
 */

import { assertCronSecret, errorResponse } from "@/app/api/_lib/responses";
import { runDigestEmailJob } from "@/server/jobs/digest-email-job";

export const dynamic = "force-dynamic";

export async function POST(request: Request): Promise<Response> {
  try {
    assertCronSecret(request);

    const result = await runDigestEmailJob(new Date());
    return Response.json(result);
  } catch (error) {
    return errorResponse(error);
  }
}

/**
 * Deterministic factories for actors, orgs, projects, issues and comments
 * used across the suite.
 *
 * Every factory seeds from the same `idFactory`, so a test that does not care
 * about ids gets stable ones, and a test that does can override them. All
 * default rows live in `ORG_A` — cross-tenant tests pass `orgId: ORG_B`.
 */
import { idFactory } from "@/lib/id";
import type { LimitCheck } from "@/types/billing";
import type { Comment } from "@/types/comment";
import type {
  CommentId,
  IsoTimestamp,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Actor, MemberWithUser, User } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";

const nextId = idFactory(42);

/** The default tenant every factory row belongs to. */
export const ORG_A = "01HZZZAAAAAAAAAAAAAAAAAAAA" as OrgId;
/** A second tenant, for cross-tenant assertions. */
export const ORG_B = "01HZZZBBBBBBBBBBBBBBBBBBBB" as OrgId;

export const ALICE = "01HZZZAAAAAAAAAAAAAAAAAAA1" as UserId;
export const BOB = "01HZZZBBBBBBBBBBBBBBBBBBB2" as UserId;

const EPOCH = "2026-03-01T09:00:00.000Z" as IsoTimestamp;

export function makeActor(overrides: Partial<Actor> = {}): Actor {
  return { userId: ALICE, orgId: ORG_A, role: "member", ...overrides };
}

export function makeUser(overrides: Partial<User> = {}): User {
  return {
    id: ALICE,
    email: "alice@example.com",
    name: "Alice Alvarez",
    avatarUrl: null,
    timezone: "UTC",
    emailVerifiedAt: EPOCH,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
  };
}

export function makeOrganization(
  overrides: Partial<Organization> = {},
): Organization {
  return {
    id: ORG_A,
    name: "Acme",
    slug: "acme",
    ownerId: ALICE,
    plan: "free",
    logoUrl: null,
    trialEndsAt: null,
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    settings: {
      defaultIssueStatus: "backlog",
      allowPublicProjects: false,
      requireTwoFactor: false,
      digestHourUtc: 8,
      enabledFlagOverrides: [],
    },
    ...overrides,
  };
}

export function makeProject(overrides: Partial<Project> = {}): Project {
  return {
    id: nextId() as ProjectId,
    orgId: ORG_A,
    name: "Website relaunch",
    slug: "website-relaunch",
    key: "WEB",
    description: null,
    visibility: "org",
    status: "active",
    leadId: ALICE,
    color: "#6366f1",
    startsAt: null,
    targetDate: null,
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
  };
}

export function makeIssue(overrides: Partial<Issue> = {}): Issue {
  return {
    id: nextId() as IssueId,
    orgId: ORG_A,
    projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
    number: 1,
    title: "Fix the broken sign-up link",
    description: null,
    status: "todo",
    priority: "medium",
    authorId: ALICE,
    assigneeId: null,
    parentId: null,
    estimate: null,
    dueAt: null,
    startedAt: null,
    completedAt: null,
    labelIds: [],
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
  };
}

export function makeComment(overrides: Partial<Comment> = {}): Comment {
  return {
    id: nextId() as CommentId,
    orgId: ORG_A,
    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
    authorId: ALICE,
    body: "Looking at this now.",
    parentId: null,
    editedAt: null,
    mentionedUserIds: [],
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
  };
}

export function makeMember(
  overrides: Partial<MemberWithUser> = {},
): MemberWithUser {
  const user = overrides.user ?? makeUser();
  return {
    id: nextId() as MemberId,
    orgId: ORG_A,
    userId: user.id,
    role: "member",
    status: "active",
    invitedBy: null,
    joinedAt: EPOCH,
    lastSeenAt: EPOCH,
    archivedAt: null,
    createdAt: EPOCH,
    updatedAt: EPOCH,
    ...overrides,
    user,
  };
}

export function makeLimitCheck(overrides: Partial<LimitCheck> = {}): LimitCheck {
  const limit = overrides.limit ?? 3;
  const used = overrides.used ?? 1;
  return {
    resource: "seats",
    plan: "free",
    limit,
    used,
    remaining: Math.max(0, limit - used),
    exceeded: used >= limit,
    ...overrides,
  };
}

/**
 * In-memory SQLite fixture: migrate, seed a tenant pair, reset between tests.
 *
 * Repository and service suites call `setupTestDb()` once, `resetTestDb()` in
 * `beforeEach` and `seedTwoTenants()` when they need two organizations to
 * prove a query is org-scoped. The database is `:memory:`, so nothing here
 * touches the developer's `data/taskflow.db`.
 */
// Aliased on import: the contract calls it `useInMemoryDb`, which the
// react-hooks lint rule would otherwise mistake for a React hook here.
import { getDb, useInMemoryDb as attachInMemoryDb } from "@/server/db";
import { runMigrations } from "@/server/db/migrate";
import { organizations } from "@/server/db/schema/organizations";
import { users } from "@/server/db/schema/users";
import type { Organization } from "@/types/organization";
import { makeOrganization, ORG_A, ORG_B } from "./factories";

let migrated = false;

/** Points the singleton client at an in-memory database and migrates it. */
export async function setupTestDb(): Promise<void> {
  attachInMemoryDb();
  await runMigrations(":memory:");
  migrated = true;
}

/** Truncates every table, keeping the schema — cheaper than re-migrating. */
export async function resetTestDb(): Promise<void> {
  if (!migrated) await setupTestDb();

  const db = getDb();
  const tables = db.$client
    .prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '__drizzle%'",
    )
    .all() as readonly { name: string }[];

  db.$client.pragma("foreign_keys = OFF");
  for (const table of tables) {
    db.$client.prepare(`DELETE FROM "${table.name}"`).run();
  }
  db.$client.pragma("foreign_keys = ON");
}

/**
 * Inserts two organizations owned by two different users. Every "does this
 * query filter by orgId?" test seeds through here so the negative case is a
 * real row in a real other tenant, not an absence.
 */
export async function seedTwoTenants(): Promise<{
  orgA: Organization;
  orgB: Organization;
}> {
  const db = getDb();

  const orgA = makeOrganization({ id: ORG_A, name: "Acme", slug: "acme" });
  const orgB = makeOrganization({
    id: ORG_B,
    name: "Globex",
    slug: "globex",
    ownerId: orgA.ownerId,
  });

  await db
    .insert(users)
    .values({
      id: orgA.ownerId,
      email: "owner@example.com",
      name: "Test Owner",
      passwordHash: "scrypt:00:00",
      timezone: "UTC",
      createdAt: orgA.createdAt,
      updatedAt: orgA.updatedAt,
    })
    .onConflictDoNothing();

  for (const org of [orgA, orgB]) {
    await db.insert(organizations).values({
      id: org.id,
      name: org.name,
      slug: org.slug,
      ownerId: org.ownerId,
      plan: org.plan,
      logoUrl: org.logoUrl,
      trialEndsAt: org.trialEndsAt,
      // `OrganizationSettings` is flattened across columns on this table.
      defaultIssueStatus: org.settings.defaultIssueStatus,
      allowPublicProjects: org.settings.allowPublicProjects,
      requireTwoFactor: org.settings.requireTwoFactor,
      digestHourUtc: org.settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(org.settings.enabledFlagOverrides),
      archivedAt: org.archivedAt,
      createdAt: org.createdAt,
      updatedAt: org.updatedAt,
    });
  }

  return { orgA, orgB };
}

