it("treats a null due date as never overdue", () => {
  expect(isOverdue(null, REFERENCE)).toBe(false);
});

it("is not overdue on the due day itself, whatever time it names", () => {
  expect(isOverdue(iso("2026-03-15T00:00:00.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T12:00:01.000Z"), REFERENCE)).toBe(false);
});

it("is overdue once the due day has ended on the workspace clock", () => {
  expect(isOverdue(iso("2026-03-14T23:59:59.000Z"), REFERENCE)).toBe(true);
  // 15 Mar 05:00 in Tokyo is still the 15th, so it is not yet overdue there.
  expect(isOverdue(iso("2026-03-14T20:00:00.000Z"), REFERENCE, "Asia/Tokyo")).toBe(false);
  // 14 Mar 23:00 in Tokyo: the 14th has ended.
  expect(isOverdue(iso("2026-03-14T14:00:00.000Z"), REFERENCE, "Asia/Tokyo")).toBe(true);
});

it("reads calendar dates on the workspace clock", () => {
  expect(localDate(iso("2026-03-14T20:00:00.000Z"), "Asia/Tokyo")).toBe("2026-03-15");
  expect(localDate(iso("2026-03-15T03:00:00.000Z"), "America/New_York")).toBe("2026-03-14");
  expect(localHour(REFERENCE, "Asia/Tokyo")).toBe(21);
});

it("finds the start of the workspace day", () => {
  expect(startOfLocalDay(REFERENCE, "UTC")).toBe("2026-03-15T00:00:00.000Z");
  expect(startOfLocalDay(REFERENCE, "Asia/Tokyo")).toBe("2026-03-14T15:00:00.000Z");
  expect(startOfLocalDaysAgo(REFERENCE, 2, "Asia/Tokyo")).toBe("2026-03-12T15:00:00.000Z");
});

it("spans 23 hours across the spring-forward change", () => {
  const window = digestWindow(1, new Date("2026-03-09T12:00:00.000Z"), "America/New_York");
  expect(window.end).toBe("2026-03-09T05:00:00.000Z");
  expect(window.start).toBe("2026-03-08T06:00:00.000Z");
});

it("takes the digest window on the workspace clock", () => {
  const window = digestWindow(8, REFERENCE, "Asia/Tokyo");
  expect(window.end).toBe("2026-03-14T23:00:00.000Z");
  expect(window.start).toBe("2026-03-13T23:00:00.000Z");
});

it("refuses a zone name Intl does not recognise", () => {
  expect(() => localDate(iso("2026-03-15T12:00:00.000Z"), "Mars/Olympus")).toThrow(RangeError);
});

